<template><div class="page"><PageState v-if="query.isLoading.value" type="loading" :title="`正在加载 ${engineName} 集群`"/><PageState v-else-if="!storage" type="error" :title="`未找到 ${engineName} 集群`"/><template v-else><section class="hero"><div><button class="hero-path" @click="back">存储集群 / {{engineName}} 集群 /</button><div class="hero-title"><h1>{{storage.name}}</h1><StatusBadge :value="storage.status??storage.deployStatus"/><t-tag class="source-tag" variant="outline">{{liveStorage?'LIVE + MOCK':'MOCK DATA'}}</t-tag></div><p>{{storage.description}}</p><div class="hero-meta"><span>{{engineName}} {{storage.version}}</span><span>{{storage.region}}</span><span>{{brokerRows.length}} Brokers</span></div></div><div class="hero-actions"><t-button variant="outline" :loading="query.isFetching.value" @click="query.refetch()"><RefreshIcon/>刷新</t-button><t-button theme="primary" @click="openTopology"><TreeRoundDotIcon/>查看拓扑</t-button></div></section><t-alert v-if="warnings.length" theme="warning" title="部分控制台数据暂不可用" :message="warnings.join('；')"/><nav class="tabs"><button v-for="item in config.panels" :key="item" :class="{active:item===panel}" @click="openPanel(item)">{{config.panelLabels[item]}}</button></nav>
  <template v-if="panel==='overview'"><MetricStrip :items="metrics"/><section class="panel deployment"><div class="section-heading"><div><h2>{{engine==='kafka'?'KRaft 部署路径':'RocketMQ 部署路径'}}</h2><p>{{engine==='kafka'?'Controller 元数据控制与消息数据面分离':'NameServer 路由发现与 Broker Group 主从同步'}}</p></div><t-tag variant="outline">{{engine==='kafka'?'KRaft':'Master / Slave'}}</t-tag></div><div class="diagram-flow"><div v-for="step in flow" :key="step.title" class="diagram-node"><strong>{{step.title}}</strong><span>{{step.note}}</span></div></div></section><div class="overview-grid"><section class="panel"><div class="section-heading"><div><h2>消息读写趋势 · Mock</h2><p>后端暂无存储吞吐时序接口</p></div><t-tag variant="outline">ANTV G2</t-tag></div><TrendChart :input="trendInput"/></section><section class="panel summary-card"><h2>集群信息</h2><p>身份字段来自可用后端；缺失的部署细节明确标记 Mock。</p><dl class="fact-list"><div><dt>版本</dt><dd>{{storage.version}}</dd></div><div><dt>控制面</dt><dd>{{engine==='kafka'?'KRaft Controller · Mock':'NameServer · Live/Mock'}}</dd></div><div><dt>Broker</dt><dd>{{brokerRows.length}}</dd></div><div><dt>关联 EventMesh</dt><dd>{{relationRows.length}}</dd></div></dl></section></div></template>
  <DataPanel v-else-if="panel==='controllers'" title="KRaft Controller · Mock" description="Controller Quorum、Leader/Follower 与 Raft 元数据日志" :data="controllers" :columns="controllerColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='nameservers'" title="NameServer" description="Broker 路由注册与客户端 Topic 路由发现" :data="nameServers" :columns="nameServerColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='brokers'" :title="`${engineName} Broker`" :description="engine==='kafka'?'Broker 与 Controller 连接、Rack 和分区承载':'Broker Group、Master/Slave 角色与同步状态'" :data="brokerRows" :columns="brokerColumns"><template #toolbar><t-button theme="primary" @click="nodeVisible=true">添加 Broker · Mock</t-button></template><template #name="{row}"><span class="identity-cell"><ServerIcon/><span><strong>{{row.name}}</strong><small>{{row.id}}</small></span></span></template><template #status="{row}"><StatusBadge :value="row.status??row.deployStatus"/></template></DataPanel>
  <DataPanel v-else-if="panel==='partitions'" title="分区副本 · Mock" description="Partition Leader、Replica 与 ISR 布局" :data="partitions" :columns="partitionColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='clients'||panel==='routes'" :title="engine==='kafka'?'Kafka 客户端 · Mock':'路由与客户端 · Mock'" description="Producer / Consumer 客户端连接与路由发现" :data="clients" :columns="clientColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template></DataPanel>
  <DataPanel v-else-if="panel==='topics'" :title="`${engineName} 物理 Topic`" description="存储中间件内部物理 Topic，与 EventMesh-facing 业务 Topic 区分" :data="topicRows" :columns="topicColumns"><template #toolbar><t-button theme="primary" @click="topicVisible=true">创建物理 Topic · Mock</t-button></template><template #status="{row}"><StatusBadge :value="row.status??'unknown'"/></template></DataPanel>
  <DataPanel v-else-if="panel==='groups'" title="消费组" description="存储中间件消费组" :data="groupRows" :columns="groupColumns"><template #status="{row}"><StatusBadge :value="row.status??'unknown'"/></template></DataPanel>
  <DataPanel v-else title="关联 EventMesh" description="引用当前存储集群的 EventMesh 集群" :data="relationRows" :columns="relationColumns"><template #status="{row}"><StatusBadge :value="row.status"/></template><template #actions="{row}"><t-button variant="text" @click="router.push(`/clusters/${row.id}/topology`)">查看拓扑</t-button></template></DataPanel>
  <t-dialog v-model:visible="nodeVisible" header="添加 Broker · Mock" @confirm="addBroker"><div class="dialog-form"><div class="dialog-note">Broker 名称使用 codex-sim- 前缀，仅保存在浏览器。</div><label>Broker 名称<t-input v-model="nodeName"/></label></div></t-dialog><t-dialog v-model:visible="topicVisible" header="创建物理 Topic · Mock" @confirm="addTopic"><div class="dialog-form"><label>Topic 名称<t-input v-model="topicName"/></label><label>分区 / 队列数<t-input-number v-model="partitionsCount" :min="1" :max="128"/></label></div></t-dialog>
  </template></div></template>
<script setup lang="ts">
import { computed,ref } from "vue";import { useRoute,useRouter } from "vue-router";import { useQuery } from "@tanstack/vue-query";import { MessagePlugin } from "tdesign-vue-next";import { RefreshIcon,ServerIcon,TreeRoundDotIcon } from "tdesign-icons-vue-next";import { dashboardRepository } from "../api/dashboardRepository";import { COMPONENT_DEFINITIONS,isComponentPanel } from "../config/clusterDefinitions";import { mockComponentClusters } from "../mock/mockClusterRelations";import { mockClusters,mockMessageSeries } from "../mock/mockClusterData";import { ensureSimName } from "../mock/mockWritableResources";import { useMockClusterStore } from "../stores/mockCluster";import MetricStrip from "../components/common/MetricStrip.vue";import StatusBadge from "../components/common/StatusBadge.vue";import PageState from "../components/common/PageState.vue";import DataPanel from "../components/common/DataPanel.vue";import TrendChart from "../components/charts/TrendChart.vue";
const route=useRoute(),router=useRouter(),store=useMockClusterStore();const clusterId=computed(()=>String(route.params.clusterId)),storageId=computed(()=>String(route.params.storageClusterId)),engine=computed(()=>route.params.engine==="rocketmq"?"rocketmq":"kafka"),engineName=computed(()=>engine.value==="kafka"?"Kafka":"RocketMQ"),config=computed(()=>COMPONENT_DEFINITIONS[engine.value]),panel=computed(()=>isComponentPanel(engine.value,route.params.panel)?String(route.params.panel):"overview");
const query=useQuery({queryKey:computed(()=>["storage-console",clusterId.value,engine.value,storageId.value]),queryFn:()=>engine.value==="kafka"?dashboardRepository.getKafkaClusterDetail(clusterId.value,storageId.value):dashboardRepository.getRocketMqClusterDetail(clusterId.value,storageId.value),retry:false});const liveStorage=computed(()=>query.data.value?.data?.storage??query.data.value?.data?.cluster??null);const storage=computed(()=>liveStorage.value??mockComponentClusters.find((x:any)=>x.id===storageId.value&&x.type===engine.value));const warnings=computed(()=>query.data.value?.meta?.warnings??[]);const liveTopics=computed(()=>query.data.value?.data?.topics??[]),liveGroups=computed(()=>query.data.value?.data?.groups??[]);const brokerRows=computed(()=>[...(storage.value?.nodes??[]),...store.resources.nodes.filter((x:any)=>x.clusterId===storageId.value)].map((x:any,i:number)=>({...x,brokerId:i,rack:`rack-${i%3+1}`,group:`broker-${String.fromCharCode(97+i%2)}`,replicaRole:i%2?"Slave":"Master",syncState:"同步 · Mock"})));const topicRows=computed(()=>[...liveTopics.value,...store.resources.physicalTopics.filter((x:any)=>x.storageClusterId===storageId.value)]);const groupRows=computed(()=>liveGroups.value);const relationRows=computed(()=>store.relations.filter((x:any)=>x.componentClusterId===storageId.value).map((rel:any)=>{const item=mockClusters.find((x:any)=>x.id===rel.eventMeshClusterId);return{id:rel.eventMeshClusterId,name:item?.name??rel.eventMeshClusterId,direction:`EventMesh → ${engineName.value}`,status:"healthy",createdAt:rel.createdAt}}));
const controllers=computed(()=>Array.from({length:3},(_,i)=>({id:`controller-${i+1}`,name:`controller-${i+1}`,nodeId:i+1,role:i===0?"Leader":"Follower",address:`10.48.0.${11+i}:9093`,term:42,logEndOffset:128400-i*3,lag:i===0?0:i*3,status:"healthy"})));const nameServers=computed(()=>Array.from({length:3},(_,i)=>({id:`nameserver-${i+1}`,name:`nameserver-${i+1}`,address:`10.58.0.${11+i}:9876`,brokers:brokerRows.value.length,routes:topicRows.value.length,lastHeartbeat:`${3+i} 秒前`,status:"healthy"})));const partitions=computed(()=>topicRows.value.flatMap((topic:any)=>Array.from({length:Math.min(3,Number(topic.partitions)||1)},(_,i)=>({id:`${topic.id}-${i}`,topic:topic.name,partition:i,leader:brokerRows.value[i%Math.max(1,brokerRows.value.length)]?.name??"—",replicas:brokerRows.value.slice(0,3).map((x:any)=>x.name).join(", "),isr:brokerRows.value.slice(0,3).map((x:any)=>x.name).join(", "),status:"healthy"}))));const clients=computed(()=>topicRows.value.flatMap((topic:any,i:number)=>[{id:`producer-${i}`,name:`producer-${i+1}`,kind:"Producer",topic:topic.name,instances:2,rate:"—",discovery:engine.value==="kafka"?"Metadata":"NameServer",status:"healthy"},{id:`consumer-${i}`,name:`consumer-${i+1}`,kind:"Consumer",topic:topic.name,instances:3,rate:"—",discovery:engine.value==="kafka"?"Group Coordinator":"NameServer",status:"healthy"}]));
const metrics=computed(()=>[{label:engine.value==="kafka"?"KRaft Controller · Mock":"NameServer · Mock",value:3,note:"后端未完整提供"},{label:"Broker · Live",value:brokerRows.value.length,note:"部署节点"},{label:"物理 Topic",value:topicRows.value.length,note:"Live + Mock"},{label:"消费组",value:groupRows.value.length,note:"Live"},{label:"关联 EventMesh",value:relationRows.value.length,note:"反向引用"}]);const flow=computed(()=>engine.value==="kafka"?[{title:"Producer",note:"选择目标分区"},{title:"Partition Leader",note:"处理消息写入"},{title:"Replicas",note:"ISR 副本同步"},{title:"Consumer",note:"按 Group 拉取"}]:[{title:"Producer / Consumer",note:"请求 Topic 路由"},{title:"NameServer",note:"发现 Broker Group"},{title:"Broker Group",note:"Master 接收消息"},{title:"Master / Slave",note:"复制与故障切换"}]);const trendInput=computed(()=>({points:mockMessageSeries.labels.flatMap((time:string,i:number)=>[{time,series:"写入",value:mockMessageSeries.inbound[i]},{time,series:"读取",value:mockMessageSeries.outbound[i]}]),unit:"K/s",source:"mock" as const,status:"ready" as const}));
const controllerColumns=[{colKey:"name",title:"Controller"},{colKey:"nodeId",title:"Node ID"},{colKey:"role",title:"角色"},{colKey:"address",title:"监听地址"},{colKey:"term",title:"Term"},{colKey:"logEndOffset",title:"Log End Offset"},{colKey:"lag",title:"复制落后"},{colKey:"status",title:"状态"}];const nameServerColumns=[{colKey:"name",title:"NameServer"},{colKey:"address",title:"监听地址"},{colKey:"brokers",title:"注册 Broker"},{colKey:"routes",title:"Topic 路由"},{colKey:"lastHeartbeat",title:"最近心跳"},{colKey:"status",title:"状态"}];const brokerColumns=computed(()=>engine.value==="kafka"?[{colKey:"name",title:"Broker"},{colKey:"brokerId",title:"Broker ID"},{colKey:"address",title:"地址"},{colKey:"rack",title:"Rack · Mock"},{colKey:"status",title:"部署状态"}]:[{colKey:"name",title:"Broker"},{colKey:"group",title:"Broker Group · Mock"},{colKey:"replicaRole",title:"角色 · Mock"},{colKey:"address",title:"地址"},{colKey:"syncState",title:"同步 · Mock"},{colKey:"status",title:"部署状态"}]);const partitionColumns=[{colKey:"topic",title:"Topic"},{colKey:"partition",title:"Partition"},{colKey:"leader",title:"Leader"},{colKey:"replicas",title:"Replicas"},{colKey:"isr",title:"ISR"},{colKey:"status",title:"状态"}];const clientColumns=[{colKey:"name",title:"客户端组"},{colKey:"kind",title:"类型"},{colKey:"topic",title:"Topic"},{colKey:"instances",title:"实例"},{colKey:"rate",title:"消息速率"},{colKey:"discovery",title:"发现方式"},{colKey:"status",title:"状态"}];const topicColumns=[{colKey:"name",title:"物理 Topic"},{colKey:"partitions",title:"分区 / 队列"},{colKey:"replicas",title:"副本"},{colKey:"inRate",title:"写入速率"},{colKey:"outRate",title:"读取速率"},{colKey:"status",title:"健康"}];const groupColumns=[{colKey:"name",title:"消费组"},{colKey:"topic",title:"Topic"},{colKey:"members",title:"实例"},{colKey:"rate",title:"消费速率"},{colKey:"lag",title:"积压"},{colKey:"status",title:"健康"}];const relationColumns=[{colKey:"name",title:"EventMesh"},{colKey:"direction",title:"关系"},{colKey:"status",title:"状态"},{colKey:"createdAt",title:"建立时间"},{colKey:"actions",title:"操作"}];
function back(){router.push({path:`/clusters/${clusterId.value}/storage`,query:{section:engine.value}})}function openPanel(next:string){router.push(`/clusters/${clusterId.value}/storage/${engine.value}/${storageId.value}/${next}`)}function openTopology(){router.push({path:`/clusters/${clusterId.value}/topology`,query:{node:`component-${storageId.value}`}})}const nodeVisible=ref(false),nodeName=ref(`codex-sim-${engine.value}-broker-new-01`);function addBroker(){const name=ensureSimName(nodeName.value,`codex-sim-${engine.value}-broker-new-01`);store.addNode({id:name,clusterId:storageId.value,name,role:`${engineName.value} Broker`,address:"待分配",status:"unknown"});nodeVisible.value=false;MessagePlugin.success("Broker 已添加")};const topicVisible=ref(false),topicName=ref("codex-sim-physical-topic"),partitionsCount=ref(12);function addTopic(){const name=ensureSimName(topicName.value,"codex-sim-physical-topic");store.addPhysicalTopic({id:`physical-${Date.now()}`,storageClusterId:storageId.value,engine:engine.value,name,partitions:partitionsCount.value,replicas:3,status:"healthy",createdAt:new Date().toISOString()});topicVisible.value=false;MessagePlugin.success("物理 Topic 已创建")}
</script>
<style scoped>.deployment{margin-bottom:12px}</style>
